/* file explorer */
.fe-head{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-bottom:1px solid var(--line)}
.fe-head .t{font-weight:600;font-size:14px}
.fe-tree{padding:8px 6px;font-size:13px}
.fe-it{display:flex;align-items:center;gap:8px;width:100%;padding:5px 10px;text-align:left;color:var(--text-dim);transition:color .2s,background-color .2s}
.fe-it:hover{color:var(--text);background:rgba(var(--fg-rgb),.025)}
.fe-it.sel{color:var(--text);background:var(--accent-bg)}
.fe-it .ms{font-size:15px;flex:none}
.fe-it .chev{transition:transform .45s var(--ease);color:var(--muted)}
.fe-it[aria-expanded="false"] .chev{transform:rotate(-90deg)}
.fe-kids{padding-left:16px;margin-left:16px;border-left:1px solid var(--line)}
.fe-b{margin-left:auto;width:18px;height:18px;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:10px;border:1px solid transparent}
.fe-b.M{color:var(--accent);border-color:var(--accent-icon-line)}
.fe-b.A{color:var(--success);border-color:rgba(62,207,142,.35)}
.fe-b.D{color:var(--danger);border-color:rgba(255,90,95,.35)}
.fe-it.del .nm{text-decoration:line-through;opacity:.7}
.fe-foot{display:flex;justify-content:space-between;gap:10px;padding:10px 16px;border-top:1px solid var(--line)}
.fe-foot .mono-xs{text-transform:none}

/* ---------- file explorer ---------- */
{
  const tree = $('#fe-tree'), path = $('#fe-path'), diff = $('#fe-diff'), count = $('#fe-count');
  const data = { n:'src', kids:[
    { n:'components', kids:[ { n:'Button.tsx', b:'M', d:'+18 -7' }, { n:'PricingCard.tsx', b:'M', d:'+42 -19' }, { n:'Toast.tsx', b:'A', d:'+96' } ] },
    { n:'styles', kids:[ { n:'tokens.css', b:'M', d:'+6 -2' }, { n:'legacy.css', b:'D', d:'-140' } ] },
    { n:'pages', closed:true, kids:[ { n:'index.tsx' }, { n:'pricing.tsx', b:'M', d:'+12 -4' } ] }
  ]};
  const badges = [];
  function node(n, p){
    const full = p ? p + '/' + n.n : n.n;
    if (n.kids){
      const w = document.createElement('div');
      w.innerHTML = `<button class="fe-it" aria-expanded="${!n.closed}"><span class="ms chev">expand_more</span><span class="ms">folder</span><span class="nm">${n.n}</span></button><div class="unfold ${n.closed ? '' : 'open'}"><div class="uf"><div class="fe-kids"></div></div></div>`;
      const kids = w.querySelector('.fe-kids'); n.kids.forEach(k => kids.appendChild(node(k, full)));
      const btn = w.querySelector('.fe-it'), fold = w.querySelector('.unfold');
      btn.addEventListener('click', () => { const open = btn.getAttribute('aria-expanded') !== 'true'; btn.setAttribute('aria-expanded', open); fold.classList.toggle('open', open); Sound.play(open ? 'open' : 'close'); });
      return w;
    }
    const b = document.createElement('button'); b.className = 'fe-it';
    b.innerHTML = `<span style="width:15px"></span><span class="ms">${n.n.endsWith('.css') ? 'tag' : 'code'}</span><span class="nm">${n.n}</span><span class="fe-b"></span>`;
    if (n.b) badges.push([b, n.b]);
    b.addEventListener('click', () => { $$('.fe-it', tree).forEach(x => x.classList.remove('sel')); b.classList.add('sel'); path.textContent = full; diff.innerHTML = n.d ? n.d.replace(/(\+\d+)/, '<span class="plus">$1</span>').replace(/(-\d+)/, '<span class="minus">$1</span>') : 'No changes'; Sound.play('tick'); });
    return b;
  }
  tree.appendChild(node(data, ''));
  function apply(){
    badges.forEach(([b]) => { const e = b.querySelector('.fe-b'); e.className = 'fe-b'; e.textContent = ''; b.classList.remove('del'); });
    badges.forEach(([b, k], i) => setTimeout(() => { const e = b.querySelector('.fe-b'); e.className = 'fe-b icon-in ' + k; e.textContent = k; if (k === 'D') b.classList.add('del'); ambient('c39', 'tick'); swapText(count, (i + 1) + ' changed'); }, 400 + i * 380));
  }
  whenSeen($('#c39'), apply);
}
